  resetCourseCounter();
  const course = createCourse({ areLabStepsAutoNumbered: autoNumber }) as any;
  const lab = createLabWithSteps(stepTitles) as any;
  return new LiveLab(course, lab, "/lab/test-course/lab-01");
}

